Context _resumeAfterPartial(
  Model model,
  AssistantMessage snapshot,
  int keptBlocks,
  StopReason reason,
  int attempt,
  int maxAttempts,
  Context context,
  _ResumeState resume,
  CancelToken? cancelToken,
) {
  resume.absorb(snapshot, keptBlocks);
  transientRetryNotice?.call(
    attempt,
    maxAttempts,
    Duration.zero,
    _midStreamResumeNotice(reason, resume.blocks.length),
  );
