          _pushTerminal(
            out,
            _partialExhaustionTerminal(
              model,
              snapshot,
              reason,
              state.attemptLog,
              resume,
              state.startedAt,
            ),
            resume,
          );
          return;
        }
        state.context = _resumeAfterPartial(
          model,
          snapshot,
          keptBlocks,
          reason,
          state.transportAttempts,
          maxAttempts,
          context,
          resume,
          cancelToken,
