/// classification, never a caller timeout.
ErrorEvent _zeroByteStallTerminal(
  Model model,
  List<String> attemptLog,
  DateTime startedAt,
) => ErrorEvent(
  reason: StopReason.error,
  error: _zeroByteStallMessage(model, attemptLog, startedAt),
