StreamFunction longLine429OnceThenCompletes() {
  var calls = 0;
  return (model, context, {cancelToken}) {
    final n = ++calls;
    final events = AssistantMessageEventStream();
    scheduleMicrotask(() { ... }); // unchanged event script
    return events;
  };
}
```

